// AuthServiceHandler is an implementation of the orkestra.v1.AuthService service.
type AuthServiceHandler interface {
	// Session auth
	Login(context.Context, *connect.Request[v1.LoginRequest]) (*connect.Response[v1.LoginResponse], error)
	Logout(context.Context, *connect.Request[v1.AuthEmpty]) (*connect.Response[v1.LogoutResponse], error)
	GetCurrentUser(context.Context, *connect.Request[v1.AuthEmpty]) (*connect.Response[v1.User], error)
	// User management (admin)
	ListUsers(context.Context, *connect.Request[v1.ListUsersRequest]) (*connect.Response[v1.ListUsersResponse], error)
	CreateUser(context.Context, *connect.Request[v1.CreateUserRequest]) (*connect.Response[v1.User], error)
	UpdateUser(context.Context, *connect.Request[v1.UpdateUserRequest]) (*connect.Response[v1.User], error)
	DeleteUser(context.Context, *connect.Request[v1.DeleteUserRequest]) (*connect.Response[v1.AuthEmpty], error)
	ResetPassword(context.Context, *connect.Request[v1.ResetPasswordRequest]) (*connect.Response[v1.AuthEmpty], error)
	SendPasswordLink(context.Context, *connect.Request[v1.SendPasswordLinkRequest]) (*connect.Response[v1.AuthEmpty], error)
	// Self-service profile management (authenticated user)
	UpdateProfile(context.Context, *connect.Request[v1.UpdateProfileRequest]) (*connect.Response[v1.User], error)
	RequestEmailChange(context.Context, *connect.Request[v1.RequestEmailChangeRequest]) (*connect.Response[v1.AuthEmpty], error)
	ConfirmEmailChange(context.Context, *connect.Request[v1.ConfirmEmailChangeRequest]) (*connect.Response[v1.AuthEmpty], error)
	// Self-service password management (authenticated user)
	ChangePassword(context.Context, *connect.Request[v1.ChangePasswordRequest]) (*connect.Response[v1.AuthEmpty], error)
	RequestPasswordReset(context.Context, *connect.Request[v1.RequestPasswordResetRequest]) (*connect.Response[v1.AuthEmpty], error)
	ResetPasswordWithToken(context.Context, *connect.Request[v1.ResetPasswordWithTokenRequest]) (*connect.Response[v1.AuthEmpty], error)
	// Role bindings (admin)
	ListRoleBindings(context.Context, *connect.Request[v1.ListRoleBindingsRequest]) (*connect.Response[v1.ListRoleBindingsResponse], error)
	AssignRole(context.Context, *connect.Request[v1.AssignRoleRequest]) (*connect.Response[v1.RoleBinding], error)
	RevokeRole(context.Context, *connect.Request[v1.RevokeRoleRequest]) (*connect.Response[v1.AuthEmpty], error)
	// OIDC config (admin)
	GetOIDCConfig(context.Context, *connect.Request[v1.AuthEmpty]) (*connect.Response[v1.OIDCConfig], error)
	UpdateOIDCConfig(context.Context, *connect.Request[v1.UpdateOIDCConfigRequest]) (*connect.Response[v1.OIDCConfig], error)
	// Password policy (admin)
	GetPasswordPolicy(context.Context, *connect.Request[v1.AuthEmpty]) (*connect.Response[v1.PasswordPolicy], error)
	UpdatePasswordPolicy(context.Context, *connect.Request[v1.PasswordPolicy]) (*connect.Response[v1.PasswordPolicy], error)
	// SMTP config (admin)
	GetSMTPConfig(context.Context, *connect.Request[v1.AuthEmpty]) (*connect.Response[v1.SMTPConfig], error)
	UpdateSMTPConfig(context.Context, *connect.Request[v1.UpdateSMTPConfigRequest]) (*connect.Response[v1.SMTPConfig], error)
	// Server config (admin)
	GetServerConfig(context.Context, *connect.Request[v1.AuthEmpty]) (*connect.Response[v1.ServerConfig], error)
	UpdateServerConfig(context.Context, *connect.Request[v1.UpdateServerConfigRequest]) (*connect.Response[v1.ServerConfig], error)
	// Enrollment tokens (admin/operator)
	ListEnrollmentTokens(context.Context, *connect.Request[v1.AuthEmpty]) (*connect.Response[v1.ListEnrollmentTokensResponse], error)
	CreateEnrollmentToken(context.Context, *connect.Request[v1.CreateEnrollmentTokenRequest]) (*connect.Response[v1.EnrollmentToken], error)
	RevokeEnrollmentToken(context.Context, *connect.Request[v1.RevokeEnrollmentTokenRequest]) (*connect.Response[v1.AuthEmpty], error)
	// API keys (self-service for current user; admin can list all)
	ListAPIKeys(context.Context, *connect.Request[v1.ListAPIKeysRequest]) (*connect.Response[v1.ListAPIKeysResponse], error)
	CreateAPIKey(context.Context, *connect.Request[v1.CreateAPIKeyRequest]) (*connect.Response[v1.APIKey], error)
	RevokeAPIKey(context.Context, *connect.Request[v1.RevokeAPIKeyRequest]) (*connect.Response[v1.AuthEmpty], error)
}

